  cmd:"python3 - <<'PY'\nimport hashlib, json\nfrom pathlib import Path\np = Path('input.md')\nscratch = Path('/private/var/folders/cs/vgp_x_353zd9frkjpysp7zdw0000gn/T/kntnt-native-session-y0lko_db/scratch')\nprint(json.dumps({'received': p.read_text(), 'source_sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'scratch_entries': sorted(x.name for x in scratch.iterdir()), 'work_entries': sorted(x.name for x in Path('.').iterdir())}, ensure_ascii=False))\nPY",
  max_output_tokens:4000
});
const data=JSON.parse(r.output);
store("redline_received",data.received);
store("redline_source_hash",data.source_sha256);
store("redline_scratch_baseline",data.scratch_entries);
store("redline_work_baseline",data.work_entries);
text({source_sha256:data.source_sha256,scratch_entries:data.scratch_entries,work_entries:data.work_entries});

let candidate=load("redline_received");
candidate=candidate.replace("## Sex veckor med dubbel registrering","## Ove Ranneby beskriver övergången");
const before="Under sex veckor registrerade personalen varje uttag både i kalkylarken och i det nya systemet. Därefter fördes kalkylarken över och stängdes.

– Vi körde parallellt i sex veckor. Sedan gick lagret över, och först då såg vi hur mycket som hade legat i pärmar, säger Ove Ranneby.";
const after="– Vi körde parallellt i sex veckor. Sedan gick lagret över till det nya systemet, och först då såg vi hur mycket som hade legat i pärmar, säger lagerchefen Ove Ranneby.

Under de veckorna registrerade personalen varje uttag både i kalkylarken och i det nya systemet. Därefter fördes kalkylarken över och stängdes.";
if(!candidate.includes(before)) throw new Error("Pre-round passage not found");
candidate=candidate.replace(before,after).replace("## Vad överföringen visade","## Hamnfrakt har inte följt upp kostnaden").replace("## Företaget vill börja mindre nästa gång","## Det tredje lagret är ännu inte överfört");
store("redline_candidate",candidate);
store("redline_current",candidate.replace("  genre: case-study
","  genre: casestudy
"));
const code = "import os, subprocess, tempfile, difflib
from pathlib import Path
candidate = "+JSON.stringify(candidate)+"
received = Path('input.md').read_text()
print(''.join(difflib.unified_diff(received.splitlines(keepends=True), candidate.splitlines(keepends=True), fromfile='received', tofile='candidate')))
with tempfile.TemporaryDirectory(prefix='redline-review-', dir='/private/var/folders/cs/vgp_x_353zd9frkjpysp7zdw0000gn/T/kntnt-native-session-y0lko_db/scratch') as tmp:
    env = dict(os.environ, TMPDIR=tmp, UV_NO_CACHE='1', UV_NO_PROJECT='1')
    result = subprocess.run(['uv', 'run', '--no-cache', '--no-project', '.agents/skills/kntnt/library/scripts/article_anatomy.py', '-'], input=candidate, text=True, env=env)
    raise SystemExit(result.returncode)
";
